function confirmPayment(ticket,amount,type,method){const r=repairs[ticket],open=due(r);if(!(amount>0)){toast('Bedrag moet groter zijn dan 0.');return}if(amount>open+0.001){toast('Bedrag mag niet groter zijn dan open saldo.');return}const seq=1000+Object.values(repairs).reduce((s,x)=>s+x.payments.length,0)+1,ref='PAY-2026-'+String(seq).padStart(5,'0');r.payments.push({id:uid('PAY'),ref,amount,method,type,at:now(),status:'confirmed'});log(r,type+' geregistreerd','',ref+' '+euro(amount)+' via '+method);if(due(r)<=0&&!r.documents.includes('Factuur'))r.documents.push('Factuur');save();overlay('Betaling ontvangen ✓',`<div class="oc" style="text-align:center"><h1>${euro(amount)}</h1><p>${esc(ref)} · ${esc(method)}</p><p>Open saldo: ${euro(due(r))}</p><div class="toolbar" style="justify-content:center"><button class="btn s" data-action="repair-open-full" data-ticket="${esc(ticket)}">Terug naar dossier</button>${r.status==='Klaar'&&due(r)<=0?`<button class="btn g" data-action="pickup" data-ticket="${esc(ticket)}">Toestel afgehaald</button>`:''}</div></div>`);}
